import type { LucideIcon } from "lucide-react"
import type { Route } from "next"

import Link from "next/link"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

export type ContentEmptyAction = {
  label: string
  href: Route | string
}

export interface ContentEmptyProps {
  icon?: LucideIcon
  title: string
  description: string
  className?: string
  primaryAction?: ContentEmptyAction
  secondaryAction?: ContentEmptyAction
}

/**
 * Inline empty state for pages and sections when a list has no data.
 */
export function ContentEmpty({
  icon: Icon,
  title,
  description,
  className,
  primaryAction,
  secondaryAction,
}: ContentEmptyProps) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center rounded-lg border border-border/70 border-dashed bg-muted/40 px-6 py-10 text-center",
        className,
      )}
      role="status"
      aria-live="polite">
      {Icon ? (
        <div className="mb-4 flex size-12 items-center justify-center rounded-full bg-background shadow-sm">
          <Icon
            className="size-6 text-muted-foreground"
            aria-hidden
          />
        </div>
      ) : null}
      <h3 className="mb-1 font-semibold text-foreground text-lg">{title}</h3>
      <p className="mb-4 max-w-md text-muted-foreground text-sm">{description}</p>
      {primaryAction || secondaryAction ? (
        <div className="flex flex-wrap justify-center gap-2">
          {primaryAction ? (
            <Button
              asChild
              size="sm">
              <Link href={primaryAction.href as Route}>{primaryAction.label}</Link>
            </Button>
          ) : null}
          {secondaryAction ? (
            <Button
              asChild
              variant="outline"
              size="sm">
              <Link href={secondaryAction.href as Route}>{secondaryAction.label}</Link>
            </Button>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

"use client"

import type { ComponentProps, ReactNode, RefObject } from "react"

import { ArrowDown } from "lucide-react"
import { useRef } from "react"

import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import { useScrollOverflowHint } from "./common-use-scroll-overflow-hint"

type ScrollOverflowHintIndicatorProps = {
  show: boolean
  tooltip: string
  onActivate: () => void
  className?: string
}

export function ScrollOverflowHintIndicator({
  show,
  tooltip,
  onActivate,
  className,
}: ScrollOverflowHintIndicatorProps) {
  if (!show) return null

  return (
    <div
      className={cn("pointer-events-none absolute inset-x-0 z-20 flex justify-center", className ?? "bottom-4")}
      aria-hidden={!show}>
      <TooltipProvider delayDuration={200}>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              type="button"
              size="icon"
              variant="outline"
              className="pointer-events-auto size-8 rounded-full border-border bg-background shadow-sm"
              aria-label={tooltip}
              onClick={onActivate}>
              <ArrowDown
                className="size-4"
                aria-hidden
              />
            </Button>
          </TooltipTrigger>
          <TooltipContent side="top">{tooltip}</TooltipContent>
        </Tooltip>
      </TooltipProvider>
    </div>
  )
}

type ScrollOverflowHintContainerProps = {
  children: ReactNode
  className?: string
  scrollClassName?: string
  tooltip: string
  hintClassName?: string
  scrollProps?: Omit<ComponentProps<"div">, "children" | "className" | "ref">
}

/** Scrollable region with a centered bottom hint when more content is available above the fold. */
export function ScrollOverflowHintContainer({
  children,
  className,
  scrollClassName,
  tooltip,
  hintClassName,
  scrollProps,
}: ScrollOverflowHintContainerProps) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const { showHint, scrollDown } = useScrollOverflowHint(scrollRef)

  return (
    <div className={cn("relative min-h-0", className)}>
      <div
        ref={scrollRef}
        className={scrollClassName}
        {...scrollProps}>
        {children}
      </div>
      <ScrollOverflowHintIndicator
        show={showHint}
        tooltip={tooltip}
        onActivate={scrollDown}
        {...(hintClassName ? { className: hintClassName } : {})}
      />
    </div>
  )
}

type ScrollOverflowHintTargetProps = {
  scrollRef: RefObject<HTMLElement | null>
  tooltip: string
  hintClassName?: string
}

/** Hint overlay for an existing scroll container (dialogs, custom panels). */
export function ScrollOverflowHintTarget({ scrollRef, tooltip, hintClassName }: ScrollOverflowHintTargetProps) {
  const { showHint, scrollDown } = useScrollOverflowHint(scrollRef)

  return (
    <ScrollOverflowHintIndicator
      show={showHint}
      tooltip={tooltip}
      onActivate={scrollDown}
      {...(hintClassName ? { className: hintClassName } : {})}
    />
  )
}

"use client"

import { startTransition, useEffect, useState } from "react"

import { cn } from "@/lib/utils"

export function ScrollProgress({ className }: { className?: string }) {
  const [progress, setProgress] = useState(0)

  useEffect(() => {
    const updateProgress = () => {
      const scrollTop = window.scrollY
      const docHeight = document.documentElement.scrollHeight - window.innerHeight
      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0
      startTransition(() => {
        setProgress(scrollPercent)
      })
    }

    updateProgress()
    window.addEventListener("scroll", updateProgress, { passive: true })
    return () => {
      window.removeEventListener("scroll", updateProgress)
    }
  }, [])

  return (
    <div
      className={cn("fixed top-0 left-0 z-[9999] h-px w-full", className)}
      aria-hidden>
      <div
        className="h-full bg-primary transition-all duration-150 ease-out"
        style={{ width: `${progress}%` }}
      />
    </div>
  )
}

"use client"

import { ArrowUpCircle } from "lucide-react"
import { useTranslations } from "next-intl"
import { startTransition, useEffect, useState } from "react"

import { Button } from "@/components/ui/button"

const SCROLL_THRESHOLD_PX = 300

export function ScrollToTopButton() {
  const t = useTranslations()
  const [isVisible, setIsVisible] = useState(false)

  useEffect(() => {
    const handleScroll = () => {
      const nextVisible = window.scrollY > SCROLL_THRESHOLD_PX
      startTransition(() => {
        setIsVisible(nextVisible)
      })
    }

    handleScroll()
    window.addEventListener("scroll", handleScroll, { passive: true })
    return () => {
      window.removeEventListener("scroll", handleScroll)
    }
  }, [])

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: "smooth",
    })
  }

  if (!isVisible) {
    return null
  }

  return (
    <div className="fixed right-3 bottom-[max(1rem,env(safe-area-inset-bottom,0px))] z-50 sm:right-4">
      <Button
        type="button"
        size="icon"
        aria-label={t("navigation.scrollToTop")}
        onClick={scrollToTop}>
        <ArrowUpCircle className="fill-primary" />
      </Button>
    </div>
  )
}

"use client"

import type { RefObject } from "react"

import { useCallback, useEffect, useState } from "react"

import {
  SCROLL_OVERFLOW_HINT_OVERFLOW_TOLERANCE_PX,
  SCROLL_OVERFLOW_HINT_SCROLL_STEP_RATIO,
  SCROLL_OVERFLOW_HINT_TOP_THRESHOLD_PX,
} from "./constants/constants-scroll-overflow-hint"

function canScrollDown(element: HTMLElement): boolean {
  return (
    element.scrollHeight > element.clientHeight + SCROLL_OVERFLOW_HINT_OVERFLOW_TOLERANCE_PX &&
    element.scrollTop <= SCROLL_OVERFLOW_HINT_TOP_THRESHOLD_PX
  )
}

export function useScrollOverflowHint(scrollRef: RefObject<HTMLElement | null>) {
  const [showHint, setShowHint] = useState(false)

  const updateHint = useCallback(() => {
    const element = scrollRef.current
    if (!element) {
      setShowHint(false)
      return
    }
    setShowHint(canScrollDown(element))
  }, [scrollRef])

  useEffect(() => {
    const element = scrollRef.current
    if (!element) return

    updateHint()

    const resizeObserver = new ResizeObserver(updateHint)
    resizeObserver.observe(element)

    const mutationObserver = new MutationObserver(updateHint)
    mutationObserver.observe(element, { childList: true, subtree: true, attributes: true, characterData: true })

    element.addEventListener("scroll", updateHint, { passive: true })
    window.addEventListener("resize", updateHint, { passive: true })

    return () => {
      resizeObserver.disconnect()
      mutationObserver.disconnect()
      element.removeEventListener("scroll", updateHint)
      window.removeEventListener("resize", updateHint)
    }
  }, [scrollRef, updateHint])

  const scrollDown = useCallback(() => {
    const element = scrollRef.current
    if (!element) return

    const remaining = element.scrollHeight - element.scrollTop - element.clientHeight
    const step = Math.max(element.clientHeight * SCROLL_OVERFLOW_HINT_SCROLL_STEP_RATIO, 120)
    element.scrollBy({ top: Math.min(step, remaining), behavior: "smooth" })
  }, [scrollRef])

  return { showHint, scrollDown, updateHint }
}

/** Re-show the hint when scroll position is within this distance from the top. */
export const SCROLL_OVERFLOW_HINT_TOP_THRESHOLD_PX = 16

/** Ignore sub-pixel overflow differences when detecting scrollable content. */
export const SCROLL_OVERFLOW_HINT_OVERFLOW_TOLERANCE_PX = 2

/** Scroll distance per hint click, as a fraction of the visible height. */
export const SCROLL_OVERFLOW_HINT_SCROLL_STEP_RATIO = 0.75

"use client"

import type { ReactNode } from "react"
import type { ConfirmationOptions } from "./confirmation-dialog-types"

import { useCallback, useRef, useState } from "react"

import { ConfirmationDialog } from "./confirmation-dialog"
import { ConfirmationDialogContext } from "./use-confirmation-dialog"

type PendingConfirmation = {
  options: ConfirmationOptions
  resolve: (confirmed: boolean) => void
}

export function ConfirmationDialogProvider({ children }: { children: ReactNode }) {
  const [pending, setPending] = useState<PendingConfirmation | null>(null)
  const pendingRef = useRef<PendingConfirmation | null>(null)

  const settle = useCallback((confirmed: boolean) => {
    const current = pendingRef.current
    if (!current) {
      return
    }

    pendingRef.current = null
    setPending(null)
    current.resolve(confirmed)
  }, [])

  const confirm = useCallback((options: ConfirmationOptions) => {
    return new Promise<boolean>((resolve) => {
      if (pendingRef.current) {
        pendingRef.current.resolve(false)
      }

      const next: PendingConfirmation = { options, resolve }
      pendingRef.current = next
      setPending(next)
    })
  }, [])

  const handleOpenChange = useCallback(
    (open: boolean) => {
      if (!open) {
        settle(false)
      }
    },
    [settle],
  )

  return (
    <ConfirmationDialogContext value={{ confirm }}>
      {children}
      <ConfirmationDialog
        open={pending !== null}
        options={pending?.options ?? null}
        onOpenChange={handleOpenChange}
        onConfirm={() => {
          settle(true)
        }}
        onCancel={() => {
          settle(false)
        }}
      />
    </ConfirmationDialogContext>
  )
}

export type ConfirmationDialogVariant = "default" | "destructive"

export type ConfirmationOptions = {
  /** Dialog title. Falls back to `common.confirmAction` when omitted. */
  title?: string
  /** Body copy shown below the title. */
  description: string
  /** Visual emphasis for destructive mutations (delete, bulk remove, etc.). */
  variant?: ConfirmationDialogVariant
  /** Primary action label. Falls back to `common.continue` when omitted. */
  confirmLabel?: string
  /** Secondary action label. Falls back to `common.cancel` when omitted. */
  cancelLabel?: string
}

export type ConfirmationDialogProps = {
  open: boolean
  options: ConfirmationOptions | null
  onOpenChange: (open: boolean) => void
  onConfirm: () => void
  onCancel: () => void
}

export type ConfirmationDialogContextValue = {
  confirm: (options: ConfirmationOptions) => Promise<boolean>
}

