"use client"

import { RefreshCwIcon } from "lucide-react"
import { useTranslations } from "next-intl"
import { memo, useCallback, useState } from "react"

import { UtilityIconButton } from "./utility-button-utility-icon-button"
import type { UtilityIconButtonProps } from "./utility-button-types"

type RefreshIconButtonProps = {
	onRefresh: () => void | Promise<void>
	/** Defaults to `common.refresh.label`. */
	label?: string | undefined
	/** Simulated minimum pending duration for demos (ms). */
	minPendingMs?: number | undefined
} & Pick<UtilityIconButtonProps, "variant" | "tooltipSide" | "className">

export const RefreshIconButton = memo(function RefreshIconButton({
	onRefresh,
	label,
	minPendingMs = 0,
	variant,
	tooltipSide,
	className,
}: RefreshIconButtonProps) {
	const t = useTranslations()
	const resolvedLabel = label ?? t("common.refresh.label")
	const [pending, setPending] = useState(false)

	const handleClick = useCallback(async () => {
		setPending(true)
		const started = Date.now()
		try {
			await onRefresh()
		} finally {
			const elapsed = Date.now() - started
			const remaining = minPendingMs - elapsed
			if (remaining > 0) {
				await new Promise((resolve) => setTimeout(resolve, remaining))
			}
			setPending(false)
		}
	}, [minPendingMs, onRefresh])

	return (
		<UtilityIconButton
			icon={RefreshCwIcon}
			label={resolvedLabel}
			loadingLabel={t("common.loading")}
			onClick={() => {
				void handleClick()
			}}
			pending={pending}
			tooltipSide={tooltipSide}
			variant={variant}
			className={className}
		/>
	)
})

"use client"

import { Loader2Icon } from "lucide-react"
import { memo } from "react"

import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import type { UtilityIconButtonProps } from "./utility-button-types"

export const UtilityIconButton = memo(function UtilityIconButton({
	label,
	tooltipLabel,
	loadingLabel,
	icon: Icon,
	onClick,
	href,
	variant = "outline",
	pending,
	isLoading,
	tooltipSide = "bottom",
	openInNewTab,
	className,
	disabled,
}: UtilityIconButtonProps) {
	const loading = pending === true || isLoading === true
	const isDisabled = disabled === true || loading
	const tooltipText = loading ? (loadingLabel ?? label) : (tooltipLabel ?? label)

	const iconNode = loading ? (
		<Loader2Icon aria-hidden className="size-4 animate-spin" />
	) : (
		<Icon aria-hidden className="size-4" />
	)

	const buttonProps = {
		size: "icon" as const,
		variant,
		className: cn(className),
		"aria-label": label,
		"aria-busy": loading || undefined,
		disabled: isDisabled,
	}

	const trigger =
		href && !onClick ? (
			<Button {...buttonProps} asChild>
				<a
					href={href}
					{...(openInNewTab
						? { target: "_blank", rel: "noopener noreferrer" }
						: {})}>
					{iconNode}
				</a>
			</Button>
		) : (
			<Button {...buttonProps} type="button" onClick={onClick}>
				{iconNode}
			</Button>
		)

	return (
		<Tooltip>
			<TooltipTrigger asChild>{trigger}</TooltipTrigger>
			<TooltipContent side={tooltipSide}>{tooltipText}</TooltipContent>
		</Tooltip>
	)
})

/** Strip locale prefix so table URL sync compares stable path segments. */
export function normalizeAppPathname(path: string): string {
  let pathname = path.split("?")[0]?.split("#")[0] ?? path
  if (!pathname.startsWith("/")) pathname = `/${pathname}`

  pathname = pathname.replace(/^\/[a-z]{2}(?:-[A-Za-z]{2})?(?=\/|$)/, "") || "/"

  if (pathname.length > 1 && pathname.endsWith("/")) {
    pathname = pathname.slice(0, -1)
  }

  return pathname || "/"
}

export function getDisplayedAppPathname(hookPathname: string): string {
  if (typeof window === "undefined") return hookPathname
  return normalizeAppPathname(window.location.pathname)
}

export function hasInFlightAppPathname(hookPathname: string): boolean {
  if (typeof window === "undefined") return false
  return getDisplayedAppPathname(hookPathname) !== normalizeAppPathname(hookPathname)
}

export function buildDisplayedAppHref(hookPathname: string, query: string): string | null {
  if (hasInFlightAppPathname(hookPathname)) return null
  const displayedPath = getDisplayedAppPathname(hookPathname)
  return query ? `${displayedPath}?${query}` : displayedPath
}
